"""Number helpers."""


def clamp(x, lo, hi):
    """Return x clamped to the range [lo, hi]."""
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def lerp(a, b, t):
    """Linear interpolation between a and b at parameter t in [0, 1]."""
    return a + (b - a) * t


