package taskpkg

// MergeStrings combines two maps; values in b override values in a on conflict.
func MergeStrings(a, b map[string]string) map[string]string {
	out := make(map[string]string, len(a)+len(b))
	for k, v := range a {
		out[k] = v
	}
	for k, v := range b {
		out[k] = v
	}
	return out
}

// CountWords returns a map from each whitespace-separated word in s to its
// occurrence count. Empty input returns an empty map.
func CountWords(s string) map[string]int {
	out := map[string]int{}
	word := ""
	flush := func() {
		if word != "" {
			out[word]++
			word = ""
		}
	}
	for _, r := range s {
		if r == ' ' || r == '\t' || r == '\n' {
			flush()
		} else {
			word += string(r)
		}
	}
	flush()
	return out
}

package taskpkg

import "testing"

func TestMergeStrings(t *testing.T) {
	a := map[string]string{"x": "1", "y": "2"}
	b := map[string]string{"y": "20", "z": "30"}
	got := MergeStrings(a, b)
	want := map[string]string{"x": "1", "y": "20", "z": "30"}
	if len(got) != len(want) {
		t.Fatalf("len = %d, want %d", len(got), len(want))
	}
	for k, v := range want {
		if got[k] != v {
			t.Errorf("[%s] = %q, want %q", k, got[k], v)
		}
	}
}

func TestCountWords(t *testing.T) {
	got := CountWords("the quick brown fox jumps over the lazy dog the")
	if got["the"] != 3 {
		t.Errorf("the = %d, want 3", got["the"])
	}
	if got["fox"] != 1 {
		t.Errorf("fox = %d, want 1", got["fox"])
	}
	if got := CountWords(""); len(got) != 0 {
		t.Errorf("empty = %v, want empty", got)
	}
}

