import (
	"testing"
	"time"
)

func TestSecondsBetween(t *testing.T) {
	a := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	b := a.Add(90 * time.Second)
	if got := SecondsBetween(a, b); got != 90 {
		t.Errorf("got %d want 90", got)
	}
	if got := SecondsBetween(b, a); got != 90 {
		t.Errorf("reversed got %d want 90", got)
	}
}

func TestIsWeekend(t *testing.T) {
	saturday := time.Date(2026, 1, 3, 12, 0, 0, 0, time.UTC) // Sat
	monday := time.Date(2026, 1, 5, 12, 0, 0, 0, time.UTC)   // Mon
	if !IsWeekend(saturday) {
		t.Error("saturday should be weekend")
	}
	if IsWeekend(monday) {
		t.Error("monday should not be weekend")
	}
}

func TestAddBusinessDays(t *testing.T) {
	fri := time.Date(2026, 1, 2, 12, 0, 0, 0, time.UTC) // Friday
	next := AddBusinessDays(fri, 1)
	if next.Weekday() != time.Monday {
		t.Errorf("Friday + 1 BD = %v, want Monday", next.Weekday())
	}
}

package taskpkg

// Gcd returns the greatest common divisor of a and b using Euclid's algorithm.
// Both inputs are taken as absolute values.
func Gcd(a, b int) int {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// IsPrime reports whether n is prime. n < 2 is not prime.
func IsPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n%2 == 0 {
		return n == 2
	}
	for i := 3; i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

// Fib returns the nth Fibonacci number with Fib(0)=0, Fib(1)=1.
// For n < 0 it returns 0.
func Fib(n int) int {
	if n < 0 {
		return 0
	}
	a, b := 0, 1
	for i := 0; i < n; i++ {
		a, b = b, a+b
	}
	return a
}

